/* Loyalty growth tools share the existing dashboard, roles and sessions. */
(()=>{'use strict';
let tab='opportunities',segment='inactive',days=30,inactiveDays=30,all=false,branch='',page=0,data=null,key='',busy=false,error='',referral=null,refKey='',refBusy=false,refreshedReferral=0;
const tabs=[['opportunities','فرص الرجوع'],['results','نتائج الولاء'],['rewards','المكافآت والدعوات'],['launch','حزمة الإطلاق']];
navOwner.push(['growth','chart','فرص الرجوع']);
function args(){return {shop:db.shop,...(db.scopedBusiness?{scope:db.scopedBusiness}:{})};}
function query(){return new URLSearchParams({...args(),days,inactiveDays,all:all?'1':'0',branchId:branch}).toString();}
function identity(){return [principal?.kind,principal?.account,principal?.member,db.shop,db.scopedBusiness].join(':');}
async function refresh(force=false){
 if(!serverMode||publicPage||role!=='owner'||view!=='growth'||busy)return;
 const next=identity()+':'+query();if(!force&&key===next)return;key=next;busy=true;error='';
 try{const result=await api('/api/growth/report?'+query());if(identity()+':'+query()===next){data=result;page=0;}}
 catch(e){if(identity()+':'+query()===next){data=null;error=e.message;}}
 finally{busy=false;if(!publicPage&&role==='owner'&&view==='growth')render();}
}
const metric=(label,value,note='')=>`<article class="growth-metric"><span>${label}</span><strong>${typeof value==='number'?fmt(value):esc(value)}</strong><small>${note}</small></article>`;
function table(rows){const shown=rows.slice(page*20,page*20+20);return `<div class="growth-table-wrap"><table class="growth-table"><thead><tr><th>العميل</th><th>البطاقة</th><th>آخر زيارة</th><th>زيارات الفترة</th><th>مكافآت جاهزة</th></tr></thead><tbody>${shown.length?shown.map(m=>`<tr><td><strong>${esc(m.name)}</strong><small dir="ltr">${esc(m.phone)}</small></td><td>${esc(m.card)}</td><td>${m.lastVisit?new Date(m.lastVisit).toLocaleDateString('ar-SA',{timeZone:'Asia/Riyadh'}):'لا توجد زيارة موثقة'}</td><td>${fmt(m.periodVisits)}</td><td>${fmt(m.available)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">لا يوجد عملاء مطابقون حاليًا.</td></tr>'}</tbody></table></div><div class="growth-pagination"><span>${fmt(rows.length)} عضوية · ${fmt(page+1)} / ${fmt(Math.max(1,Math.ceil(rows.length/20)))}</span><button class="btn quiet small" data-growth-page="-1" ${page===0?'disabled':''}>السابق</button><button class="btn quiet small" data-growth-page="1" ${(page+1)*20>=rows.length?'disabled':''}>التالي</button></div>`;}
function selectedRows(){return (data?.rows||[]).filter(m=>segment==='inactive'?m.inactive:segment==='near'?m.nearReward:segment==='ready'?m.available>0:m.neverVisited);}
function opportunities(){const labels={inactive:'عملاء منقطعون',near:'قريبون من المكافأة',ready:'مكافآتهم جاهزة',new:'سجّلوا ولم يزوروا'},rows=selectedRows();return `<div class="growth-segments">${Object.keys(labels).map(k=>`<button class="growth-segment ${segment===k?'selected':''}" data-growth-segment="${k}"><span>${labels[k]}</span><strong>${fmt(data.segments[k])}</strong><small>${k==='inactive'?'من آخر زيارة موثقة':k==='near'?'تبقّى لهم رصيد زيارة واحدة':k==='ready'?'استحقوا مكافأة ولم يستخدموها':'لم تُسجّل لهم زيارة'}</small></button>`).join('')}</div><section class="panel growth-panel"><div class="panel-head"><div><h2>${labels[segment]}</h2><p>اختر إجراء مناسبًا لهذه المجموعة.</p></div><div class="actions"><button class="btn secondary small" data-growth-copy-message>نص جاهز للتواصل</button><button class="btn quiet small" data-growth-export>تصدير المجموعة</button></div></div>${table(rows)}<p class="growth-note">التصدير يحفظ أسماء المجموعة وأرقامها واسم البطاقة فقط. التواصل يختاره صاحب النشاط؛ لا تُرسل رسائل تلقائيًا من هذه الصفحة.</p></section>`;}
function results(){const m=data.metrics;return `<div class="growth-metrics">${metric('عملاء نشطون',m.active,'عضويات لها زيارة خلال الفترة')}${metric('عملاء عائدون',m.returning,'لديهم زيارة سابقة موثقة')}${metric('نسبة العودة',m.returnRate+'٪','من العملاء النشطين في الفترة')}${metric('زيارات مسجلة',m.visits,'العمليات المتراجع عنها مستبعدة')}${metric('مكافآت مصروفة',m.redeemed,'تم تسجيل صرفها خلال الفترة')}${metric('مشتريات مسجلة',m.sales,'ريال · تغطية المبالغ '+m.coverage+'٪')}</div><section class="panel growth-panel"><div class="panel-head"><div><h2>نتائج الفروع</h2><p>الأرقام من العمليات المسجلة، ولا تشمل مبالغ لم يدخلها الموظف.</p></div></div><div class="growth-table-wrap"><table class="growth-table"><thead><tr><th>الفرع</th><th>الزيارات</th><th>المكافآت المصروفة</th><th>المشتريات المسجلة</th><th>زيارات لها مبلغ</th></tr></thead><tbody>${data.branches.length?data.branches.map(b=>`<tr><td>${esc(b.name)}</td><td>${fmt(b.visits)}</td><td>${fmt(b.redeemed)}</td><td>${fmt(b.sales)} ريال</td><td>${fmt(b.recorded)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">تظهر النتائج بعد تسجيل العمليات.</td></tr>'}</tbody></table></div><div class="growth-note">نسبة العودة تعتمد على الزيارات الموثقة، والمشتريات تعرض المبالغ المسجلة فقط؛ لا تمثل إيرادًا إضافيًا مضمونًا سببه الولاء. العميل المشترك في بطاقتين يُحسب عضوية في كل بطاقة.</div></section><div class="growth-metrics compact">${metric('دعوات مسجلة',data.referrals.joined)}${metric('دعوات تنتظر الاعتماد',data.referrals.pending)}${metric('دعوات استحقت المكافأة',data.referrals.awarded)}</div>`;}
function rewards(){const sh=shop(),settings=data.settings,choices=sh.card.rewardChoices||[],discount=Loyalty.program(sh.card).type==='discount';return `<section class="panel growth-panel"><div class="panel-head"><div><h2>اختيار المكافأة</h2><p>خيارات واضحة تُصرف من الرصيد نفسه، دون مضاعفة الاستحقاق.</p></div></div><form id="growth-settings"><label class="field"><span>خيارات المكافآت · خيار في كل سطر</span><textarea class="input" name="choices" rows="5" maxlength="280" ${discount?'disabled':''} placeholder="قهوة مجانية&#10;قطعة حلوى&#10;ترقية حجم المشروب">${esc(choices.map(c=>c.label).join('\n'))}</textarea><small>${discount?'برنامج الخصم يحتفظ بقيمة الخصم المحددة في البطاقة.':'حتى ستة خيارات. جميعها تحتاج الرصيد المعتاد للبطاقة. اتركها فارغة للإبقاء على المكافأة الأساسية.'}</small></label><div class="growth-note">المكافآت المستحقة سابقًا تبقى وفق شروطها القديمة. الخيارات الجديدة تنطبق على الاستحقاقات الجديدة، وعلى صرف رصيد النقاط عند توفره.</div><div class="growth-divider"></div><h2>دعوة صديق</h2><p class="sub">رابط خاص لكل عميل. مكافأة للطرفين بعد أول زيارة للصديق بمبلغ مسجّل أكبر من صفر.</p><label class="terms mt"><input type="checkbox" name="enabled" ${settings.referralsEnabled?'checked':''}>تفعيل دعوة صديق لهذه البطاقة</label><label class="field mt"><span>مكافأة الدعوة لكل طرف</span><input class="input" name="reward" maxlength="45" required value="${esc(settings.referralReward||'مكافأة دعوة صديق')}" placeholder="مشروب صغير مجاني"></label><p class="growth-note">تظهر مكافأة الدعوة بعد انتهاء مهلة التراجع عن الزيارة، خلال نحو 6 دقائق. الزيارة بلا مبلغ مسجّل لا تؤهل الدعوة؛ إضافة المبلغ اختيارية لبقية العمليات.</p><button class="btn primary" type="submit">حفظ المكافآت والدعوات</button><p class="error" role="alert" id="growth-settings-error"></p></form></section>`;}
function launch(){const c=shop().card,name=c.name||shop().name,url=registrationURL(db.shop,branch),text=`صار لزياراتك مكافأة عند ${name}!\nانضم لبرنامج الولاء من الرابط، واحتفظ ببطاقتك على جوالك.\n${programSummary(c)}\n${url}`;return `<div class="growth-launch-grid"><section class="panel growth-panel"><h2>ملصق التسجيل</h2><p class="sub">اختر الفرع من الأعلى قبل الطباعة لربط التسجيل به.</p><div id="growth-poster" class="growth-poster"><img src="/brand-logo.png" width="160" alt="رجعة"><h3>${esc(name)}</h3><p>كل زيارة تقرّبك من مكافأتك</p><div class="growth-poster-qr">${qr(url)}</div><strong>امسح الرمز وانضم لبرنامج الولاء</strong><small>${esc(programSummary(c))}</small><small>بطاقتك على جوالك</small></div><button class="btn primary full" data-growth-print>طباعة الملصق</button></section><section class="panel growth-panel"><h2>منشور الإعلان</h2><p class="sub">جاهز للنسخ، وتقدر تعدله بما يناسب نشاطك.</p><textarea class="input growth-copy" id="growth-launch-text" rows="7">${esc(text)}</textarea><button class="btn secondary mt" data-growth-copy-launch>نسخ المنشور والرابط</button><div class="growth-divider"></div><h2>شرح قصير للموظف</h2><p class="growth-script">«عندنا برنامج ولاء. امسح الرمز وسجّل اسمك وجوالك، واحتفظ ببطاقتك. كل زيارة مؤهلة تقرّبك من ${esc(Loyalty.label(c))}، وأنا أسجلها لك من البطاقة.»</p><div class="growth-divider"></div><h2>خطوات الإطلاق</h2><ol class="growth-checklist"><li>راجع المكافأة وشروط الاستحقاق.</li><li>أضف موظفًا وجرّب المسح والصرف.</li><li>علّق ملصق التسجيل عند الكاشير.</li><li>عرّف العملاء بالبرنامج عند الزيارة.</li><li>راجع «نتائج الولاء» بعد أول أسبوع.</li></ol></section></div>`;}
const previousOwner=ownerHTML;
ownerHTML=function(){if(view!=='growth')return previousOwner();const active=shop();if(!serverMode)return head('نمو نشاطك','فرص الرجوع','تتوفر هذه الأدوات في حساب النشاط الفعلي.');if(!active)return '';const branches=(active.branches||[]).filter(b=>tab!=='launch'||(b.status==='active'&&appliesToBranch(active.card,b.id)));if(tab==='launch'&&branch&&!branches.some(b=>b.id===branch))branch='';return head('نمو نشاطك','فرص الرجوع','عملاء تعرفهم، وفرص تستفيد منها.','<button class="btn secondary small" data-growth-refresh>تحديث النتائج</button>')+`<nav class="growth-tabs" aria-label="أدوات نمو النشاط">${tabs.map(([id,label])=>`<button class="${tab===id?'active':''}" data-growth-tab="${id}">${label}</button>`).join('')}</nav><div class="growth-toolbar"><label>البطاقة<select class="input" data-growth-filter="card">${db.shops.filter(s=>!s.archivedAt).map(s=>`<option value="${esc(s.id)}" ${s.id===db.shop?'selected':''}>${esc(s.card.title||s.name)}</option>`).join('')}</select></label>${['opportunities','results'].includes(tab)?`<label>النطاق<select class="input" data-growth-filter="all"><option value="0" ${!all?'selected':''}>هذه البطاقة</option><option value="1" ${all?'selected':''}>جميع بطاقات النشاط</option></select></label><label>فترة النتائج<select class="input" data-growth-filter="days">${[7,30,90,365].map(n=>`<option value="${n}" ${days===n?'selected':''}>آخر ${fmt(n)} يومًا</option>`).join('')}</select></label>`:''}<label>الفرع<select class="input" data-growth-filter="branch"><option value="">جميع الفروع</option>${branches.map(b=>`<option value="${esc(b.id)}" ${branch===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label>${tab==='opportunities'?`<label>مدة الانقطاع<select class="input" data-growth-filter="inactiveDays">${[14,30,60,90].map(n=>`<option value="${n}" ${inactiveDays===n?'selected':''}>${fmt(n)} يومًا</option>`).join('')}</select></label>`:''}</div>${error?`<div class="panel"><p class="error">${esc(error)}</p><button class="btn secondary" data-growth-refresh>إعادة المحاولة</button></div>`:!data||key!==identity()+':'+query()?'<div class="panel" role="status">جارٍ تحميل بيانات نشاطك…</div>':tab==='opportunities'?opportunities():tab==='results'?results():tab==='rewards'?rewards():launch()}`;};
async function customerReferral(){const next=identity();if((refKey===next&&Date.now()-refreshedReferral<30000)||refBusy)return;refKey=next;refreshedReferral=Date.now();refBusy=true;try{const result=await api('/api/growth/referral?shop='+encodeURIComponent(db.shop));if(identity()===next){const changed=JSON.stringify(referral)!==JSON.stringify(result);referral=result;if(changed)render();}}catch{referral=null;}finally{refBusy=false;}}
const previousRender=render;
render=function(){previousRender();if(!serverMode||publicPage)return;
 if(role==='owner'&&view==='growth'){void refresh();return;}
 if(role==='client'&&clientStage==='card'){
  const host=document.querySelector('.enroll-issued-panel,.customer-card-panel,.phone-layout'),m=currentMember(),sh=shop();if(!host||!m||!sh)return;
  const choices=Loyalty.nextChoices(m,sh.card);
  if(choices.length)host.insertAdjacentHTML('beforeend',`<section class="growth-customer-box"><h3>اختر مكافأتك الجاهزة</h3><p>اختر واحدة، ثم اعرض بطاقتك للموظف ليصرفها.</p><form id="growth-choice"><select class="input" name="choice" aria-label="المكافأة المختارة">${choices.map(c=>`<option value="${esc(c.id)}" ${m.rewardChoiceId===c.id?'selected':''}>${esc(c.label)}</option>`).join('')}</select><button class="btn primary full mt" type="submit">تأكيد الاختيار</button></form>${m.rewardChoiceId?'<small>اختيارك محفوظ. الصرف يتم لدى الموظف.</small>':''}</section>`);
  if(refKey!==identity())referral=null;
  if(referral?.enabled)host.insertAdjacentHTML('beforeend',`<section class="growth-customer-box"><h3>ادعُ صديقًا</h3><p>لك ولصديقك ${esc(referral.reward)} بعد أول زيارة له بمبلغ مسجّل.</p><button class="btn secondary full" data-growth-referral-copy>نسخ رابط دعوتي</button><small>${fmt(referral.joined)} دعوات انضمت · ${fmt(referral.earned)} دعوات استحقت المكافأة</small></section>`);
  void customerReferral();
 }
};
const previousScan=processScan;
processScan=async function(code){if(requestBusy||document.querySelector('#growth-staff-redeem'))return;if(!serverMode||staffMode!=='redeem')return previousScan(code);const sh=shop();let id=String(code).trim();if(id.startsWith('RIJAA:')){const parts=id.split(':');if(parts[1]!==sh.id)return previousScan(code);id=parts[2];}const m=sh.members.find(x=>x.id===id),choices=m?Loyalty.nextChoices(m,sh.card):[];if(!choices.length)return previousScan(code);
 scannerLock=true;modal('اختيار المكافأة',`<p>${esc(m.name)} · يتم صرف مكافأة واحدة.</p><form id="growth-staff-redeem"><input type="hidden" name="code" value="${esc(code)}"><label class="field"><span>المكافأة</span><select class="input" name="choice" aria-label="المكافأة المختارة">${choices.map(c=>`<option value="${esc(c.id)}" ${m.rewardChoiceId===c.id?'selected':''}>${esc(c.label)}</option>`).join('')}</select></label><button class="btn primary full" type="submit">تأكيد الصرف</button><p class="error" role="alert"></p></form>`);
};
document.querySelector('#modal')?.addEventListener('close',()=>{scannerLock=false;});
function downloadCSV(rows){const safe=v=>{let s=String(v??'');if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv='\uFEFF'+[['الاسم','الجوال','البطاقة'],...rows.map(m=>[m.name,m.phone,m.card])].map(r=>r.map(safe).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='رجعة-مجموعة-'+segment+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(value){await navigator.clipboard.writeText(value);toast('تم النسخ.');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-growth-tab],[data-growth-segment],[data-growth-page],[data-growth-refresh],[data-growth-export],[data-growth-copy-message],[data-growth-copy-launch],[data-growth-print],[data-growth-referral-copy]');if(!b)return;e.preventDefault();try{
 if(b.dataset.growthTab){tab=b.dataset.growthTab;page=0;render();}
 else if(b.dataset.growthSegment){segment=b.dataset.growthSegment;page=0;render();}
 else if(b.dataset.growthPage){page=Math.max(0,page+Number(b.dataset.growthPage));render();}
 else if(b.hasAttribute('data-growth-refresh'))await refresh(true);
 else if(b.hasAttribute('data-growth-export'))downloadCSV(selectedRows());
 else if(b.hasAttribute('data-growth-copy-message')){const sh=shop(),texts={inactive:`اشتقنا لزيارتك في ${sh.card.name||sh.name}. بطاقتك ومزاياك بانتظارك. يسعدنا نشوفك من جديد.`,near:`باقي لك رصيد زيارة مؤهلة واحدة لاستحقاق مكافأتك في ${sh.card.name||sh.name}. اعرض بطاقتك عند زيارتك القادمة.`,ready:`مكافأتك جاهزة في ${sh.card.name||sh.name}! اعرض بطاقة الولاء للموظف للاستفادة منها.`,new:`أهلًا بك في برنامج ولاء ${sh.card.name||sh.name}. ابدأ أول زيارة مؤهلة، وخلي مكافأتك أقرب.`};modal('نص جاهز للمجموعة',`<label class="field"><span>راجع النص وأضف عرضك إن رغبت</span><textarea class="input" rows="5" id="growth-message-text">${esc(texts[segment])}</textarea></label><button class="btn primary" type="button" data-growth-copy-launch>نسخ النص</button>`);}
 else if(b.hasAttribute('data-growth-copy-launch'))await copy(document.querySelector('#growth-message-text,#growth-launch-text').value);
 else if(b.hasAttribute('data-growth-referral-copy'))await copy(referral.url);
 else if(b.hasAttribute('data-growth-print')){document.body.classList.add('growth-print');window.print();}
 }catch(err){toast(err.message||'تعذر تنفيذ الإجراء.');}
});
document.addEventListener('change',async e=>{const filter=e.target.dataset.growthFilter;if(!filter)return;const value=e.target.value;try{if(filter==='card'){const oldRole=role,oldView=view;acceptServer(await api('/api/state?shop='+encodeURIComponent(value)+(db.scopedBusiness?'&scope='+encodeURIComponent(db.scopedBusiness):'')));role=oldRole;view=oldView;branch='';}else if(filter==='all')all=value==='1';else if(filter==='days')days=Number(value);else if(filter==='inactiveDays')inactiveDays=Number(value);else branch=value;data=null;render();}catch(err){toast(err.message);}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['growth-settings','growth-choice','growth-staff-redeem'].includes(form.id))return;e.preventDefault();e.stopImmediatePropagation();const button=form.querySelector('button[type=submit]');if(button.disabled)return;button.disabled=true;const values=new FormData(form);try{
 if(form.id==='growth-settings'){await api('/api/growth/settings',{...args(),referralsEnabled:values.has('enabled'),referralReward:values.get('reward'),choices:String(values.get('choices')||'').split('\n').map(s=>s.trim()).filter(Boolean).map(label=>({label}))});const oldRole=role,oldView=view;acceptServer(await api('/api/state?shop='+encodeURIComponent(db.shop)+(db.scopedBusiness?'&scope='+encodeURIComponent(db.scopedBusiness):'')));role=oldRole;view=oldView;await refresh(true);toast('تم حفظ المكافآت والدعوات.');}
 else if(form.id==='growth-choice'){await api('/api/growth/choice',{shop:db.shop,choiceId:values.get('choice')});acceptServer(await api('/api/state'));refKey='';render();toast('تم حفظ اختيارك.');}
 else{const result=await serverCommand({action:'redeem',code:values.get('code'),rewardChoiceId:values.get('choice'),requestId:crypto.randomUUID()},{redraw:false});lastTx={...result,shop:shop().id,undone:false};document.querySelector('#modal').close();render();toast('تم صرف '+result.reward.label);}
 }catch(err){const el=form.querySelector('.error');if(el)el.textContent=err.message;else toast(err.message);}finally{button.disabled=false;}
},true);
setInterval(()=>{if(serverMode&&!publicPage&&role==='client'&&clientStage==='card'&&!document.hidden&&!document.querySelector('dialog[open]')&&!document.activeElement?.closest('form'))void customerReferral();},30000);
window.addEventListener('afterprint',()=>document.body.classList.remove('growth-print'));
render();
})();
